import{_ as n,o,c as a,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const b=JSON.parse('{"title":"Combined finance","description":"","frontmatter":{"title":"Combined finance"},"headers":[],"relativePath":"docs/personal-finance/combined-finance.md","filePath":"docs/personal-finance/combined-finance.md","lastUpdated":1794529254000}'),r={name:"docs/personal-finance/combined-finance.md"};function s(c,e,i,d,l,p){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="combined-finance" tabindex="-1">Combined finance <a class="header-anchor" href="#combined-finance" aria-label="Permalink to &quot;Combined finance&quot;">​</a></h1><p>A <strong>Standard Workbook</strong> brings selected finance projects into one view. Earlier versions called this Combined Finance. The statements stay in the source projects; the workbook uses their updated records as you add more history.</p><h2 id="connect-the-picture" tabindex="-1">Connect the picture <a class="header-anchor" href="#connect-the-picture" aria-label="Permalink to &quot;Connect the picture&quot;">​</a></h2><p>Choose <strong>New Workbook</strong> on the Dashboard, select Standard Workbook, and choose the projects to include. Later, use <strong>Add Sources</strong> to connect another project. See <a href="/docs/concepts/workbooks">Workbooks</a>.</p><p>Depending on the source projects, the workbook can show:</p><ul><li>Combined bank and card spending, income and categories.</li><li>Investment holdings, allocation and performance across accounts.</li><li>Net worth across financial accounts, tracked assets and debts.</li><li>Debt balances and progress across linked loans.</li></ul><p>Use the available focus views and recipes to explore a part of the picture. Drill into a result to inspect the records behind it.</p><p>For retirement assumptions and scenarios, create a separate <a href="/docs/personal-finance/retirement">Retirement Planning workbook</a> using the relevant projects.</p>',8)])])}const m=n(r,[["render",s]]);export{b as __pageData,m as default};
